<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';
$hash='CHAR(64) CHARACTER SET ascii';
$sql=[
"CREATE TABLE cloud_accounts(id $id PRIMARY KEY,enabled BOOLEAN NOT NULL DEFAULT TRUE,environment VARCHAR(16) NOT NULL CHECK(environment='mock')) ENGINE=InnoDB",
"CREATE TABLE cloud_catalog(id $id PRIMARY KEY,account_id $id NOT NULL,product_id $id NOT NULL,snapshot LONGTEXT NOT NULL CHECK(JSON_VALID(snapshot)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(account_id) REFERENCES cloud_accounts(id),FOREIGN KEY(product_id) REFERENCES catalog_products(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_instances(id $id PRIMARY KEY,service_id $id NOT NULL UNIQUE,customer_id $id NOT NULL,account_id $id NOT NULL,catalog_id $id NOT NULL,spec_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,imported BOOLEAN NOT NULL DEFAULT FALSE,status VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROVISIONING','ACTIVE','STOPPED','UNKNOWN','TERMINATED','FAILED')),resource_id $id NULL UNIQUE,provider_resource_ref VARCHAR(128) CHARACTER SET ascii NULL,current_operation_id $id NULL,generation INT UNSIGNED NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY uq_cloud_provider_resource(account_id,provider_resource_ref),FOREIGN KEY(service_id) REFERENCES svc_services(id),FOREIGN KEY(account_id) REFERENCES cloud_accounts(id),FOREIGN KEY(catalog_id) REFERENCES cloud_catalog(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_operations(id $id PRIMARY KEY,instance_id $id NOT NULL,kind VARCHAR(24) NOT NULL CHECK(kind IN ('CREATE','START','STOP','RESTART','REINSTALL','UPGRADE','TERMINATE')),generation INT UNSIGNED NOT NULL,request_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','WAITING_TASK','POLLING','SUCCEEDED','FAILED','UNKNOWN','MANUAL_REVIEW')),lease_token $id NULL,lease_until DATETIME(6) NULL,task_id $id NULL UNIQUE,resource_id $id NULL,safe_code VARCHAR(64) NOT NULL DEFAULT 'QUEUED',runner_checked_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_cloud_generation(instance_id,generation),KEY ix_cloud_pending(status,runner_checked_at,created_at,id),KEY ix_cloud_expiry(status,lease_until,id),FOREIGN KEY(instance_id) REFERENCES cloud_instances(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_dispatches(operation_id $id PRIMARY KEY,lease_token $id NOT NULL,fingerprint $hash NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(operation_id) REFERENCES cloud_operations(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_observations(id $id PRIMARY KEY,operation_id $id NOT NULL,instance_version BIGINT UNSIGNED NOT NULL,evidence_encrypted LONGTEXT NOT NULL,fingerprint $hash NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(operation_id) REFERENCES cloud_operations(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_confirmations(id $id PRIMARY KEY,instance_id $id NOT NULL,instance_version BIGINT UNSIGNED NOT NULL,kind VARCHAR(24) NOT NULL,payload_hash $hash NOT NULL,actor_id VARCHAR(64) NOT NULL,expires_at DATETIME(6) NOT NULL,not_before DATETIME(6) NOT NULL,consumed BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(instance_id) REFERENCES cloud_instances(id)) ENGINE=InnoDB",
"CREATE TABLE cloud_effects(operation_id $id PRIMARY KEY,instance_id $id NOT NULL,account_id $id NOT NULL,task_id $id NOT NULL UNIQUE,resource_id $id NOT NULL,resource_version BIGINT UNSIGNED NOT NULL,kind VARCHAR(24) NOT NULL,state VARCHAR(24) NOT NULL,provider_task_ref VARCHAR(128) CHARACTER SET ascii NOT NULL,provider_resource_ref VARCHAR(128) CHARACTER SET ascii NOT NULL,provenance VARCHAR(16) NOT NULL CHECK(provenance='MOCK'),observed_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(operation_id) REFERENCES cloud_operations(id),UNIQUE KEY uq_cloud_provider_task(account_id,provider_task_ref),KEY ix_cloud_usage_provenance(resource_id,observed_at,operation_id)) ENGINE=InnoDB",
"CREATE TABLE cloud_history(id $id PRIMARY KEY,instance_id $id NOT NULL,operation_id $id NULL,kind VARCHAR(64) NOT NULL,trace_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(instance_id) REFERENCES cloud_instances(id)) ENGINE=InnoDB",
"CREATE TABLE mock_voyar_resources(id $id PRIMARY KEY,account_id $id NOT NULL,provider_ref VARCHAR(128) CHARACTER SET ascii NOT NULL UNIQUE,create_operation_id $id NOT NULL UNIQUE,last_operation_id $id NOT NULL,spec_json LONGTEXT NOT NULL CHECK(JSON_VALID(spec_json)),state VARCHAR(24) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,FOREIGN KEY(account_id) REFERENCES cloud_accounts(id)) ENGINE=InnoDB",
"CREATE TABLE mock_voyar_tasks(id $id PRIMARY KEY,account_id $id NOT NULL,provider_ref VARCHAR(128) CHARACTER SET ascii NOT NULL UNIQUE,operation_id $id NOT NULL UNIQUE,resource_id $id NOT NULL,fingerprint $hash NOT NULL,kind VARCHAR(24) NOT NULL,state VARCHAR(32) NOT NULL DEFAULT 'MOCK_PENDING',payload_json LONGTEXT NOT NULL CHECK(JSON_VALID(payload_json)),FOREIGN KEY(resource_id) REFERENCES mock_voyar_resources(id)) ENGINE=InnoDB",
"CREATE TABLE mock_voyar_calls(operation_id $id PRIMARY KEY,account_id $id NOT NULL,fingerprint $hash NOT NULL,kind VARCHAR(24) NOT NULL,task_id $id NULL,resource_id $id NULL,outcome VARCHAR(24) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(account_id) REFERENCES cloud_accounts(id)) ENGINE=InnoDB",
"CREATE TRIGGER cloud_instance_binding BEFORE UPDATE ON cloud_instances FOR EACH ROW BEGIN IF OLD.service_id<>NEW.service_id OR OLD.customer_id<>NEW.customer_id OR OLD.account_id<>NEW.account_id OR OLD.catalog_id<>NEW.catalog_id OR OLD.spec_encrypted<>NEW.spec_encrypted OR OLD.fingerprint<>NEW.fingerprint OR OLD.imported<>NEW.imported OR (OLD.resource_id IS NOT NULL AND NOT(OLD.resource_id <=> NEW.resource_id)) OR (OLD.provider_resource_ref IS NOT NULL AND NOT(OLD.provider_resource_ref <=> NEW.provider_resource_ref)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable Cloud instance binding'; END IF; END",
"CREATE TRIGGER cloud_operation_binding BEFORE UPDATE ON cloud_operations FOR EACH ROW BEGIN IF OLD.instance_id<>NEW.instance_id OR OLD.kind<>NEW.kind OR OLD.generation<>NEW.generation OR OLD.request_encrypted<>NEW.request_encrypted OR OLD.fingerprint<>NEW.fingerprint OR (OLD.task_id IS NOT NULL AND NOT(OLD.task_id <=> NEW.task_id)) OR (OLD.status IN ('SUCCEEDED','FAILED') AND NEW.status<>OLD.status) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable Cloud operation binding'; END IF; END",
];
foreach(['cloud_catalog','cloud_dispatches','cloud_observations','cloud_effects','cloud_history','mock_voyar_calls'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable Cloud evidence'";}}
foreach(['cloud_instances','cloud_operations'] as $table){$sql[]="CREATE TRIGGER {$table}_delete BEFORE DELETE ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Cloud history retained'";}
return $sql;
